  'decouvertes-histoire': {
    section: 'decouvertes', kicker: 'Histoire', image: 'assets/lagoon.png',
    title: 'Histoire de la commune',
    lead: 'Grand-Popo est un ancien royaume Xwla et un grand comptoir historique du golfe de Guinee.',
    blocks: [
      { type: 'prose', body: `
        <p>Ne des vestiges du royaume Xwla, Grand-Popo est un centre historique majeur entre le fleuve Mono et l ocean Atlantique. La commune a connu les echanges commerciaux regionaux puis les comptoirs europeens.</p>
        <p>Le 12 avril 1885, Grand-Popo passe sous protectorat francais. Son role administratif et commercial se renforce avant le deplacement progressif des activites vers Cotonou au XXe siecle.</p>
        <p>Aujourd hui, la commune valorise cette memoire historique dans une dynamique touristique, culturelle et citoyenne.</p>` }
    ]
  },
  'decouvertes-patrimoine-historique': {
    section: 'decouvertes', kicker: 'Patrimoine historique', image: 'assets/facade.jpg',
    title: 'Patrimoine historique',
    lead: 'Patrimoine historique de la commune de Grand-Popo.',
    blocks: [
      { type: 'prose', body: `
        <h2>Patrimoine historique de la commune</h2>
        <p>Ancien centre de commerce d esclaves, impregnee d un passe colonial et historique fascinant, la commune de Grand-Popo conserve encore les vestiges pittoresques restes encore vivaces d un passe historique riche et fascinant, avec des forts et des batiments coloniaux qui temoignent de son histoire mouvementee. Le Fort de Grand-Popo, construit au 18eme siecle par les Portugais, est l un des sites historiques les plus emblematiques de la commune, offrant aux visiteurs un voyage dans le temps, une histoire vivante de la region a travers ces sites historiques.</p>
        <h3>Sites historiques</h3>
        <ul>
          <li>Bureau du garde de cercle de Grand-Popo</li>
          <li>Residence Olympio de Gbecon</li>
          <li>Ancienne Residence du medecin en Chef de Grand-Popo</li>
          <li>Marche colonial de Gbecon</li>
          <li>Marche colonial de Adjaha</li>
          <li>Comptoir Ajavon de Gbecon</li>
          <li>Coffre-fort-colonial-dAdjaha</li>
          <li>Cimetiere d Agoue</li>
          <li>Chenin-de-lesclave-dAgoue</li>
          <li>Comptoir-Portugais-John-Walt-de-Gbecon</li>
          <li>Bunker-Tranchee-de-Heve</li>
          <li>Batiment-colonial-abritant-le-bureau-de-larrondissement-dAgoue</li>
          <li>Ancienne-prison-civile-de-Grand-Popo</li>
          <li>Ancienne-poste-de-Grand-Popo</li>
          <li>Ancienne-maternite-de-Grand-Popo</li>
          <li>Ancienne-mairie-de-Grand-Popo</li>
          <li>Ancienne-douane-de-Gbecon</li>
          <li>Ancienne-Auberge-de-Grand-Popo</li>
          <li>Ancien-bloc-de-traitement-des-epidemies-de-Grand-Popo</li>
          <li>Ancien ou vieux pont de Grand-Popo</li>
        </ul>` }
    ]
  },
